document.addEventListener('input',event=>{if(event.target.id==='zoom-slider'){scene.zoom=.065*Math.pow(2.1/.065,Number(event.target.value)/100);scene.updateCamera();return;}if(event.target.id==='build-search'||event.target.id==='army-search'){const field=event.target.id,pos=event.target.selectionStart,value=event.target.value;if(field==='build-search'){buildSearch=value;buildPage=0;}else{armySearch=value;armyPage=0;}renderPanel();const next=document.getElementById(field);if(next){next.focus();next.setSelectionRange(pos,pos);}return;}if(event.target.id==='sound-volume'){state.settings.volume=Number(event.target.value)/100;sound.volume=state.settings.volume;save();}});document.addEventListener('change',event=>{if(event.target.id==='frontier-level'){frontierFilters.level=Number(event.target.value);dirty=true;}if(event.target.id==='frontier-biome'){frontierFilters.biome=event.target.value;dirty=true;}if(event.target.id==='sound-enabled'){state.settings.sound=event.target.checked;sound.enabled=state.settings.sound;sound.unlock();save();}});
$('#import-file').addEventListener('change',async event=>{const file=event.target.files[0];event.target.value='';if(!file)return;if(file.size>3000000){toast('La copia supera el tamaño permitido.');return;}try{pendingImport=E.decode(await file.text());if(!pendingImport.world)E.upgradeToIslands(pendingImport,true);E.initGarrison(pendingImport);modal(head('RESTABLECER PARTIDA','Tu copia está preparada.')+'<p>'+GAME.hq+' nivel '+E.hqLevel(pendingImport)+' · '+pendingImport.buildings.length+' edificios · '+pendingImport.army.length+' tropas. Esta copia reemplazará la base local de este juego.</p><div class="action-row"><button data-action="export">Exportar base actual</button><button class="primary" data-action="confirm-import">Importar esta copia</button></div>');}catch(error){toast('No se pudo importar: '+error.message);}});
function showSector(id){if(!id)return;const q=E.expansionQuote(state,id),p=E.sectorOrigin(id),owned=state.world.owned.includes(id);scene.focus.x=p.x+5;scene.focus.z=p.y+5;scene.updateCamera();modal(head('TERRITORIO · SECTOR '+id,owned?'Este terreno es tuyo.':id>72?'Zona de escenarios enemigos.':'Amplía tu base.')+'<p>'+(owned?'Puedes construir sobre el suelo despejado de este sector.':q.message||'Incorpora 100 casillas contiguas a tu territorio. La compra no construye automáticamente un puente.')+'</p>'+(!owned&&id<=72?cost(q.cost):'')+'<div class="action-row"><button data-action="close-modal">Volver al mapa</button>'+(!owned&&q.ok?'<button class="primary" data-action="expand" data-index="'+id+'" '+(!E.affordable(state,q.cost)?'disabled':'')+'>Comprar sector</button>':'')+'</div>');}
const groups=new Map();document.addEventListener('keydown',event=>{if(event.target.matches('input,textarea,select')||$('#modal').open)return;const k=event.key.toLowerCase();if(k==='escape'){abilityMode=null;operationTarget=null;expansionMode=false;scene.expansionMode=false;workerOrderMode=false;tool=null;moving=null;candidate=null;selected=[];tab='base';dirty=true;}if(k===' '){event.preventDefault();scene.home(state);}if(state.battle){if(k==='a'){command='attack';deployType=null;dirty=true;}if(k==='s')for(const u of state.battle.units.filter(u=>selected.includes(u.id)))u.order={kind:'hold',x:u.x,y:u.y};if(/^[1-9]$/.test(k)){if(event.ctrlKey){event.preventDefault();groups.set(k,[...selected]);}else selected=groups.get(k)||[];}}});
function paintOverlay(){const r=$('#field').getBoundingClientRect(),dpr=Math.min(devicePixelRatio||1,1.5);if(overlay.width!==Math.round(r.width*dpr)||overlay.height!==Math.round(r.height*dpr)){overlay.width=Math.round(r.width*dpr);overlay.height=Math.round(r.height*dpr);}ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,r.width,r.height);if(!scene)return;const b=state.battle,buildings=b?.buildings||state.buildings;for(const building of buildings){if(building.hp<=0)continue;if(b&&!visibleAt(b,building.x,building.y,true))continue;const size=building.size||E.BUILDINGS[building.type].size,p=scene.screen(building.x+size/2,building.y+size/2,2),spec=E.BUILDINGS[building.type];if(p.x<0||p.x>r.width||p.y<0||p.y>r.height)continue;if(building.job){const ratio=(state.time-building.job.started)/(building.job.ends-building.job.started);ctx.fillStyle='#122c2bd9';ctx.fillRect(p.x-23,p.y-5,46,6);ctx.fillStyle='#dbc487';ctx.fillRect(p.x-23,p.y-5,46*Math.min(1,ratio),6);}else if(!b&&spec.resource&&building.stored>=10){ctx.fillStyle='#1b3629e8';ctx.beginPath();ctx.roundRect(p.x-20,p.y-11,40,22,5);ctx.fill();ctx.fillStyle='#e3c17c';ctx.font='600 10px Segoe UI';ctx.textAlign='center';ctx.fillText('+'+fmt(building.stored),p.x,p.y+4);}if(b){const max=building.maxHp||E.buildingStats(building.type,building.level).hp;ctx.fillStyle='#14332ade';ctx.fillRect(p.x-21,p.y-8,42,4);ctx.fillStyle=building.side==='enemy'?'#dc8e76':'#adc9a4';ctx.fillRect(p.x-21,p.y-8,42*building.hp/max,4);}}
 if(b)for(const u of b.units.filter(u=>u.hp>0&&!u.embarked&&!u.evacuated&&(u.side==='player'||visibleAt(b,u.x,u.y)))){if(u.hp>=u.maxHp&&!selected.includes(u.id))continue;const p=scene.screen(u.x,u.y,E.UNITS[u.type].flying?3:1.3);ctx.fillStyle='#16312ee0';ctx.fillRect(p.x-12,p.y-8,24,3);ctx.fillStyle=u.side==='enemy'?'#e5937b':'#bbd59f';ctx.fillRect(p.x-12,p.y-8,24*u.hp/u.maxHp,3);}if(scene.selectionRect){const box=scene.selectionRect,rect=scene.canvas.getBoundingClientRect();ctx.fillStyle='#c1dba41c';ctx.strokeStyle='#c1dba4';ctx.fillRect(box.x-rect.x,box.y-rect.y,box.x2-box.x,box.y2-box.y);ctx.strokeRect(box.x-rect.x,box.y-rect.y,box.x2-box.x,box.y2-box.y);}}
addEventListener('pagehide',save);document.addEventListener('visibilitychange',()=>{if(document.hidden){save();}lastFrame=performance.now();});
try{await ready;}catch(error){setHTML($('#loading'),'<p>No se pudieron cargar los dibujos del juego.</p><small>Comprueba tu conexión y vuelve a abrir la página. Tu partida se conserva.</small>');throw error;}try{scene=new Battlefield($('#world'),pick);}catch(error){setHTML($('#loading'),'<span class="loading-mark">A</span><p>Este navegador no pudo iniciar el mapa.</p><small>Prueba una versión actual de Chrome, Edge, Firefox o Safari.</small><button onclick="location.reload()">Volver a intentar</button>');throw error;}
scene.state=state;scene.home(state);$('#loading').remove();render();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'}).catch(()=>{});
if(loadError)modal(head('REVISAR COPIA LOCAL','La partida necesita revisión.')+'<p>'+esc(loadError)+'. La copia original se conserva y el guardado está detenido. Exporta el archivo para conservarlo, importa una copia válida o crea una base nueva.</p><div class="action-row"><button data-action="export">Exportar copia original</button><button data-action="import">Importar copia</button><button data-action="recover-save">Revisar recuperación local</button><button data-action="new-dialog">Nueva base</button></div>');else if(!state.tutorial)guide();
let lastFrame=performance.now(),lastUi=0,lastPaint=0,lastShot=0;function frame(now){const dt=Math.max(0,Math.min(.12,(now-lastFrame)/1000));lastFrame=now;if(!document.hidden&&!loadError){const previous=state.battle,buildCount=state.buildings.filter(b=>b.job).length;if($('#modal').open)E.tickEconomy(state,dt);else E.step(state,dt);if(previous&&!state.battle){abilityMode=null;operationTarget=null;selected=[];deployType=null;tab='base';save();battleResult();dirty=true;scene.home(state);}if(!previous&&state.battle){tab='base';selected=[];sound.play('alert');save();dirty=true;scene.home(state);}if(state.battle?.effects.length&&now-lastShot>250){const shot=state.battle.effects.at(-1);if(state.battle.elapsed-shot.at<.13){sound.play('attack');lastShot=now;}}if(buildCount!==state.buildings.filter(b=>b.job).length){sound.play('complete');dirty=true;}if(now-lastUi>900){renderHud();if(!document.activeElement.matches('input,select')){renderPanel();renderInspector();renderDock();combatTools.hidden=!state.battle;setHTML(combatTools,state.battle?skillsPanel(state,selected,{esc,clock})+(abilityMode||operationTarget?'<div class="ability-hint">Marca el objetivo en el mapa.<button data-action="cancel-ability">Cancelar</button></div>':''):'');}nav();lastUi=now;if(state.time-lastSave>8)save();}if(dirty)render();if(now-lastPaint>40){scene.draw(state,{selected,placement:tool==='clear'?null:tool||state.buildings.find(b=>b.id===moving)?.type});paintOverlay();lastPaint=now;}}requestAnimationFrame(frame);}requestAnimationFrame(frame);

if('serviceWorker'in navigator)navigator.serviceWorker.addEventListener('message',event=>{if(event.data?.game!==GAME.id+'-')return;const button=$('[data-action=offline-download]'),data=event.data;if(button){button.disabled=data.type==='offline-progress';button.textContent=data.type==='offline-complete'?'Juego completo disponible sin conexión':data.type==='offline-error'?'Reintentar descarga sin conexión':'Descargando '+data.done+' / '+data.total;}if(data.type==='offline-complete')toast('Todos los gráficos y el juego están disponibles sin conexión.');if(data.type==='offline-error')toast('La descarga quedó incompleta. Puedes reintentar cuando vuelva la conexión.');});
